public enum CryptoError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidSecretKey(message: String)
    
    case InvalidPublicKey(message: String)
    
    case InvalidEphemeralKey(message: String)
    
    case EcdhFailed(message: String)
    
    case EncryptionFailed(message: String)
    
    case DecryptionFailed(message: String)
    
    case HexError(message: String)
    
    case InvalidNonce(message: String)
    
    case InvalidCiphertext(message: String)
    
    case KeyDerivationFailed(message: String)
    
    case SignatureVerificationFailed(message: String)
    
    case JsonError(message: String)
    
    case WrongPin(message: String)
    
    case InvalidPin(message: String)
    
    case InvalidInput(message: String)
    
    case InvalidFormat(message: String)
    
    case HkdfExpandError(message: String)
    
    case InvalidSignature(message: String)
    
    case StaleTimestamp(message: String)
    
    case FutureTimestamp(message: String)
    
    /**
     * An identifier outside the §2.1 profile (`^[0-9a-z][0-9a-z-]{0,63}$` or lowercase hex).
     */
    case InvalidIdentifier(message: String)
    
    /**
     * No relay-event key is held for this hub and epoch.
     */
    case NoEventKey(message: String)
    
    /**
     * The hub has no admin reader to seal to. See [`crate::readers`].
     */
    case NoAdminReader(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

